"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8048],{64143:e=>{e.exports=JSON.parse('{"functions":[{"name":"adjustValueByUserPriceLevel","desc":"Returns `value` multiplied by the player\'s price-level factor.\\n\\nThe level reported by [getPriceLevel] (1 to 1000) maps linearly onto a multiplier\\nof 0.001 to 1.0, so the price only ever moves downward from the level-1000\\nbaseline. Yields on the first lookup per player.\\n\\nWhen the price level is unavailable \u2014 a failed or throttled lookup \u2014 `value` is\\nreturned unchanged rather than discounted.\\n\\nThe result is not rounded; round it yourself before showing or charging it.","params":[{"name":"player","desc":"Player being priced for","lua_type":"Player"},{"name":"value","desc":"Baseline price to scale","lua_type":"number"}],"returns":[{"desc":"Adjusted price","lua_type":"number"}],"function_type":"static","realm":["Server"],"source":{"line":32,"path":"src/Shared/Modules/adjustValueByUserPriceLevel.luau"}}],"properties":[],"types":[],"name":"adjustValueByUserPriceLevel","desc":"Scales a Robux price by the player\'s regional price level.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":9,"path":"src/Shared/Modules/adjustValueByUserPriceLevel.luau"}}')}}]);